def slugify(s):
    s = s.lower()
    out = []
    for ch in s:
        if ch == 'õ':
            ch = 'o'
        if ch.isalnum():
            out.append(ch)
        elif ch in (' ', '-', '_'):
            if out and out[-1] != '-':
                out.append('-')
    return ''.join(out).rstrip('-')

_TRANSLIT = {
    'õ': 'o', 'ö': 'o', 'ä': 'a', 'ä': 'a', 'ü': 'u',
    'š': 's', 'ž': 'z', 'č': 'c', 'ď': 'd', 'ť': 't',
    'ľ': 'l', 'ŕ': 'r', 'ĺ': 'l', 'ň': 'n', 'í': 'i',
    'é': 'e', 'á': 'a', 'ú': 'u', 'ý': 'y',
}


def slugify(s):
    s = s.lower()
    out = []
    prev_sep = True
    for ch in s:
        if ch in _TRANSLIT:
            out.append(_TRANSLIT[ch])
            prev_sep = False
        elif ch.isalnum():
            out.append(ch)
            prev_sep = False
        else:
            # Any non-alnum char (space, punctuation, '-') is a separator.
            if not prev_sep:
                out.append('-')
            prev_sep = True
    return ''.join(out)

